import torch
import triton
import triton.language as tl

# -----------------------------------------------------------------------------
# Triton kernel: Fused 2D Transposed Convolution
#
# Loops over kernel spatial dims and input‐channel group in one pass.
# Accumulates in fp32 for stability, then casts to bf16 on store.
# Supports arbitrary asymmetric kernel sizes, padding, dilation, stride, and groups.
# -----------------------------------------------------------------------------


@triton.jit
def _conv_transpose2d_kernel(
    # Pointers
    x_ptr,
    w_ptr,
    out_ptr,
    total_elements,
    # Tensor dims (constexpr)
    batch: tl.constexpr,
    in_c: tl.constexpr,
    in_h: tl.constexpr,
    in_w: tl.constexpr,
    out_c: tl.constexpr,
    out_h: tl.constexpr,
    out_w: tl.constexpr,
    k_h: tl.constexpr,
    k_w: tl.constexpr,
    s_h: tl.constexpr,
    s_w: tl.constexpr,
    p_h: tl.constexpr,
    p_w: tl.constexpr,
    d_h: tl.constexpr,
    d_w: tl.constexpr,
    groups: tl.constexpr,
    in_c_per_g: tl.constexpr,
    out_c_per_g: tl.constexpr,
    # Strides (in elements)
    x_stride_b: tl.constexpr,
    x_stride_c: tl.constexpr,
    x_stride_h: tl.constexpr,
    x_stride_w: tl.constexpr,
    w_stride_ic: tl.constexpr,
    w_stride_oc: tl.constexpr,
    w_stride_kh: tl.constexpr,
    w_stride_kw: tl.constexpr,
    out_stride_b: tl.constexpr,
    out_stride_c: tl.constexpr,
    out_stride_h: tl.constexpr,
    out_stride_w: tl.constexpr,
    # Block size
    BLOCK: tl.constexpr,
):
    """
    Each program computes BLOCK flattened output elements.
    """

    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask_o = offs < total_elements

    # Flattened index -> (n, co, i_out, j_out)
    nc = out_c * out_h * out_w
    n = offs // nc
    rem = offs % nc
    co = rem // (out_h * out_w)
    rem2 = rem % (out_h * out_w)
    i_out = rem2 // out_w
    j_out = rem2 % out_w

    # FP32 accumulator per lane
    acc = tl.zeros((BLOCK,), dtype=tl.float32)

    # Which group & local output‐channel
    group_id = co // out_c_per_g
    cin_start = group_id * in_c_per_g
    co_local = co - group_id * out_c_per_g

    # Loop over kernel H×W
    for kh_i in range(k_h):
        # invert transposed conv formula in H dimension:
        #   i_out = i_in * s_h - p_h + kh * d_h
        #   => i_in = (i_out + p_h - kh*d_h) / s_h   only valid if divisible
        in_i_numer = i_out + p_h - kh_i * d_h
        in_i = in_i_numer // s_h
        valid_h = (in_i_numer == in_i * s_h) & (in_i >= 0) & (in_i < in_h)

        for kw_j in range(k_w):
            in_j_numer = j_out + p_w - kw_j * d_w
            in_j = in_j_numer // s_w
            valid_w = (in_j_numer == in_j * s_w) & (in_j >= 0) & (in_j < in_w)

            # final per‐lane validity mask
            valid_spatial = mask_o & valid_h & valid_w

            # sum over input‐channels in this group
            for ci in range(in_c_per_g):
                c_in = cin_start + ci
                x_off = (
                    n * x_stride_b
                    + c_in * x_stride_c
                    + in_i * x_stride_h
                    + in_j * x_stride_w
                )
                x_val = tl.load(x_ptr + x_off, mask=valid_spatial, other=0.0).to(
                    tl.float32
                )
                w_off = (
                    c_in * w_stride_ic
                    + co_local * w_stride_oc
                    + kh_i * w_stride_kh
                    + kw_j * w_stride_kw
                )
                w_val = tl.load(w_ptr + w_off, mask=mask_o, other=0.0).to(tl.float32)
                acc += x_val * w_val

    # cast acc to bf16 and store
    out_val = acc.to(out_ptr.dtype.element_ty)
    out_off = (
        n * out_stride_b
        + co * out_stride_c
        + i_out * out_stride_h
        + j_out * out_stride_w
    )
    tl.store(out_ptr + out_off, out_val, mask=mask_o)


def kernel_function(
    x: torch.Tensor,
    weight: torch.Tensor,
    bias,
    stride: tuple,
    padding: tuple,
    dilation: tuple,
    groups: int,
):
    """
    Wrapper for grouped 2D transposed convolution on Intel XPU using Triton.
    """

    # 1) Validate arguments
    assert bias is None, "Bias must be None for this kernel"
    assert x.dtype in (torch.bfloat16, torch.float16) and weight.dtype == x.dtype, (
        "Inputs must be float16 or bfloat16"
    )

    # 2) Shapes
    batch, in_c, in_h, in_w = x.shape
    # PyTorch conv_transpose2d weight: [in_c, out_c/groups, k_h, k_w]
    in_c_w, out_c_pg, k_h, k_w = weight.shape
    assert in_c_w == in_c
    out_c = out_c_pg * groups

    s_h, s_w = stride
    p_h, p_w = padding
    d_h, d_w = dilation
    in_c_per_g = in_c // groups
    out_c_per_g = out_c // groups

    # compute output H, W
    out_h = (in_h - 1) * s_h - 2 * p_h + d_h * (k_h - 1) + 1
    out_w = (in_w - 1) * s_w - 2 * p_w + d_w * (k_w - 1) + 1

    # 3) Allocate output
    out = torch.empty((batch, out_c, out_h, out_w), device=x.device, dtype=x.dtype)

    # 4) Flattened element count
    total_elems = batch * out_c * out_h * out_w

    # 5) Strides (in elements)
    x_stride_b, x_stride_c, x_stride_h, x_stride_w = x.stride()
    w_stride_ic, w_stride_oc, w_stride_kh, w_stride_kw = weight.stride()
    out_stride_b, out_stride_c, out_stride_h, out_stride_w = out.stride()

    # 6) Launch parameters
    BLOCK = 256
    grid = (triton.cdiv(total_elems, BLOCK),)

    # 7) Launch kernel
    _conv_transpose2d_kernel[grid](
        # pointers + total
        x,
        weight,
        out,
        total_elems,
        # dims
        batch,
        in_c,
        in_h,
        in_w,
        out_c,
        out_h,
        out_w,
        k_h,
        k_w,
        s_h,
        s_w,
        p_h,
        p_w,
        d_h,
        d_w,
        groups,
        in_c_per_g,
        out_c_per_g,
        # strides
        x_stride_b,
        x_stride_c,
        x_stride_h,
        x_stride_w,
        w_stride_ic,
        w_stride_oc,
        w_stride_kh,
        w_stride_kw,
        out_stride_b,
        out_stride_c,
        out_stride_h,
        out_stride_w,
        # block size
        BLOCK,
    )
    return out


