import torch.nn as nn


class Model(nn.Module):
    """
    Performs a 2D transposed convolution operation with asymmetric input, asymmetric kernel,
    grouped, padded, and dilated.

    Args:
        in_channels (int): Number of channels in the input tensor.
        out_channels (int): Number of channels produced by the convolution.
        kernel_size (tuple): Size of the convolution kernel (height, width).
        stride (tuple, optional): Stride of the convolution (height, width). Defaults to (1, 1).
        padding (tuple, optional): Padding applied to the input (height, width). Defaults to (0, 0).
        dilation (tuple, optional): Spacing between kernel elements (height, width). Defaults to (1, 1).
        groups (int, optional): Number of blocked connections from input channels to output channels. Defaults to 1.
        bias (bool, optional): If `True`, adds a learnable bias to the output. Defaults to `False`.
    """

    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: tuple,
        stride: tuple = (1, 1),
        padding: tuple = (0, 0),
        dilation: tuple = (1, 1),
        groups: int = 1,
        bias: bool = False,
    ):
        super(Model, self).__init__()
        # Keep the same init signature as the reference Model, but route compute to Triton kernel.
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = (
            tuple(stride) if isinstance(stride, (list, tuple)) else (stride, stride)
        )
        self.padding = (
            tuple(padding) if isinstance(padding, (list, tuple)) else (padding, padding)
        )
        self.dilation = (
            tuple(dilation)
            if isinstance(dilation, (list, tuple))
            else (dilation, dilation)
        )
        self.groups = groups
        self.use_bias = bias

        # Kernel wrapper constraints
        assert not self.use_bias, "Bias must be False / None for this kernel"
        assert len(self.stride) == 2, "stride must have 2 elements (sh, sw)"
        assert len(self.padding) == 2, "padding must have 2 elements (ph, pw)"
        assert len(self.dilation) == 2, "dilation must have 2 elements (dh, dw)"
        assert isinstance(self.groups, int) and self.groups >= 1, (
            "groups must be a positive int"
        )
        assert in_channels % self.groups == 0, "in_channels must be divisible by groups"
        assert out_channels % self.groups == 0, (
            "out_channels must be divisible by groups"
        )

        k_h, k_w = kernel_size
        # Match nn.ConvTranspose2d parameter shapes:
        # weight: (in_channels, out_channels/groups, k_h, k_w)
        self.weight = nn.Parameter(
            torch.empty(in_channels, out_channels // self.groups, k_h, k_w)
        )
        self.bias = None

        # Reasonable init
        nn.init.kaiming_uniform_(self.weight, a=5**0.5)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Performs the 2D transposed convolution.

        Args:
            x (torch.Tensor): Input tensor of shape (batch_size, in_channels, height, width).

        Returns:
            torch.Tensor: Output tensor of shape (batch_size, out_channels, height_out, width_out).
        """
        return kernel_function(
            x,
            self.weight,
            self.bias,
            self.stride,
            self.padding,
            self.dilation,
            self.groups,
        )


